INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66122495', 66122495, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Suku Cadang Sistem Website Aviation', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 79842000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '2 Buah', 'Keselamatan penerbangan adalah aspek krusial yang tidak dapat dipisahkan dari kondisi cuaca. Dalam konteks ini, kecepatan, ketepatan, dan keakuratan diseminasi informasi cuaca menjadi faktor penentu keselamatan penerbangan. Informasi yang disampaikan secara cepat dan akurat memungkinkan maskapai penerbangan, pilot, dan pihak terkait lainnya untuk membuat keputusan yang tepat demi menghindari potensi bahaya yang disebabkan oleh perubahan cuaca ekstrem. Badan Meteorologi, Klimatologi, dan Geofisika (BMKG) mengemban amanah besar dalam menyediakan dan menyebarluaskan informasi cuaca penerbangan. Salah satu kanal utama yang digunakan BMKG untuk mendiseminasikan informasi vital ini adalah sistem website aviation. Website ini berfungsi sebagai platform sentral yang memungkinkan akses cepat dan mudah terhadap data cuaca penerbangan terkini. Mengingat peran vital ini, keberadaan sistem yang efisien dan andal sangatlah krusial untuk mendukung kinerja sumber daya manusia (SDM) BMKG dalam menjalankan tugas sehari-hari. Namun, seiring berjalannya waktu dan perkembangan teknologi, serta untuk memastikan kinerja yang optimal dan berkelanjutan, pemeliharaan sistem website aviation yang ada saat ini menjadi suatu keharusan. Pemeliharaan ini tidak hanya berfokus pada perbaikan teknis, tetapi juga pada peningkatan fungsionalitas dan optimalisasi kinerja sistem secara keseluruhan. Dengan pemeliharaan yang terencana dan terstruktur, diharapkan sistem website ini dapat secara signifikan memudahkan dan mempercepat pekerjaan pegawai BMKG, baik di kantor pusat maupun di daerah. Ini mencakup proses pembuatan, koreksi, dan diseminasi informasi cuaca penerbangan kepada berbagai pihak, mulai dari stasiun meteorologi, operator penerbangan, hingga masyarakat umum.', 'Suku Cadang untuk sistem website Aviation', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2562894);
