INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66130266', 66130266, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL KEPENDUDUKAN DAN PENCATATAN SIPIL', 'PRODUKSI DIGITAL DAN MEDIA FISIK UNTUK REBRANDING DUKCAPIL', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 1292850000, 'March 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '10 PKT', '1.Memproduksi materi komunikasi publik dalam bentuk media digital dan fisik sesuai dengan Brand Identity Document dan strategi komunikasi yang telah ditetapkan. 2.Mendukung pelaksanaan kampanye komunikasi publik terkait transformasi digital layanan administrasi kependudukan. 3.Memastikan konsistensi identitas visual dan pesan komunikasi Dukcapil di seluruh kanal komunikasi. 4.Mendukung penyebarluasan informasi layanan administrasi kependudukan kepada masyarakat secara luas. 5.Mendukung pelaksanaan kegiatan publikasi, kampanye, dan aktivasi komunikasi publik Dukcapil di tingkat nasional dan daerah.', '1.Produksi media digital dan fisik untuk Re-branding Dukcapil, termasuk produksi materi visual komunikasi publik, materi audiovisual, serta materi komunikasi cetak sesuai dengan panduan identitas merek yang telah ditetapkan; 2.Publikasi media sosial melalui berbagai platform digital, seperti Instagram, TikTok, YouTube, dan platform media sosial lainnya, guna mendukung penyebarluasan informasi layanan administrasi kependudukan kepada masyarakat; 3.Publikasi media online melalui portal berita berbasis web, baik media nasional maupun daerah, guna meningkatkan jangkauan informasi kepada masyarakat; 4.Publikasi media cetak melalui surat kabar nasional dan daerah, guna mendukung penyampaian informasi kepada masyarakat secara lebih luas; 5.Publikasi media televisi melalui penayangan materi komunikasi publik Dukcapil, guna memperkuat visibilitas kelembagaan dan meningkatkan jangkauan komunikasi kepada masyarakat; 6.Publikasi media cetak majalah, termasuk majalah nasional, majalah khusus, dan majalah penerbangan, guna memperluas jangkauan komunikasi kepada segmen masyarakat tertentu; dan 7.Publikasi media massa melalui distribusi siaran pers (press release), artikel, dan materi komunikasi publik lainnya kepada media massa, guna mendukung penyebarluasan informasi dan memperkuat pemberitaan terkait Dukcapil.', 258570000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2569938);
